import java.util.*;

//I know I could've optimized this code but I just wanted to have an example made
class Solution {

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        int fc = in.nextInt();
        int vc = in.nextInt();
        int revenue = in.nextInt();
        float tempRev = revenue;
        int tc = (fc+vc);
        int profit = (int) revenue - tc;
        int margin = revenue==0 ? -100 : Math.round(((profit/tempRev)*100));
        String ans = "";
        if(profit==0){
            ans = "BREAK-EVEN";
        }
        else if(profit>0){
            ans = "PROFITABLE | Net: " + profit + " | Margin: " + margin + "%";
        }
        else{
            ans = "LOSS | Net: " + profit + " | Margin: " + margin + "%";
        }

        System.out.println(ans);
    }
}
